params.command:
$ErrorActionPreference='Stop'
$relay=Join-Path $HOME 'HeavenBridgeRepo'
$origin=(git -C $relay remote get-url origin).Trim()
$tmp=Join-Path $env:TEMP ('runner-single-session-'+[guid]::NewGuid().ToString('N'))
git clone --quiet --branch fix/heaven-runner-single-session-20260929 --single-branch $origin $tmp
if($LASTEXITCODE -ne 0){ exit $LASTEXITCODE }
try {
  $sha=(git -C $tmp rev-parse HEAD).Trim()
  $script=Join-Path $tmp 'heaven-bridge\install-github-runner.ps1'
  $tokens=$null; $errors=$null
  [System.Management.Automation.Language.Parser]::ParseFile($script,[ref]$tokens,[ref]$errors) | Out-Null
  if($errors.Count -gt 0){ $errors | ForEach-Object { Write-Error $_.Message }; exit 1 }
  Set-Location $tmp
  python .\heaven-bridge\test_worker.py
  if($LASTEXITCODE -ne 0){ exit $LASTEXITCODE }
  python .\heaven-bridge\tests\test_worker.py
  if($LASTEXITCODE -ne 0){ exit $LASTEXITCODE }
  git diff --check
  if($LASTEXITCODE -ne 0){ exit $LASTEXITCODE }
  Write-Output ('VERIFIED_SHA='+$sha)
} finally {
  Set-Location $HOME
  Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
}
